```typescript
import { expect, Locator, Page } from '@playwright/test';
import { BasePage } from './BasePage';

/**
 * Page Object for the Doctor List/Provider Page.
 * Handles displaying and interacting with a list of medical practitioners.
 */
export class DoctorsPage extends BasePage {
  public readonly doctorListContainer: Locator;
  public readonly doctorCards: Locator;
  public readonly doctorName: (card: Locator) => Locator;
  public readonly doctorSpecialty: (card: Locator) => Locator;
  public readonly doctorAvailability: (card: Locator) => Locator;
  public readonly bookAppointmentButton: (card: Locator) => Locator; // Added for booking appointments
  public readonly paginationNextButton: Locator;

  /**
   * Constructor for DoctorsPage.
   * @param page The Playwright Page object.
   */
  constructor(page: Page) {
    super(page);
    this.doctorListContainer = page.locator('[data-testid="doctor-list"]');
    this.doctorCards = page.locator('[data-testid="doctor-card"]'); // Each individual doctor entry
    this.doctorName = (card: Locator) => card.getByRole('heading', { level: 2 });
    this.doctorSpecialty = (card: Locator) => card.locator('[data-testid="doctor-specialty"]');
    this.doctorAvailability = (card: Locator) => card.locator('[data-testid="doctor-availability"]');
    this.bookAppointmentButton = (card: Locator) => card.getByRole('button', { name: 'Book Appointment' }); // New locator for booking
    this.paginationNextButton = page.getByRole('button', { name: 'Next Page' }) || page.getByRole('link', { name: 'Next' });
  }

  /**
   * Verifies that the doctor list is displayed and not empty.
   */
  public async verifyDoctorListDisplayed(): Promise<void> {
    await expect(this.doctorListContainer).toBeVisible();
    await expect(this.doctorCards).toHaveCount(expect.toBeGreaterThan(0));
  }

  /**
   * Retrieves details for all displayed doctors.
   * @returns A Promise that resolves to an array of objects, each containing doctor details.
   */
  public async getDoctorDetails(): Promise<{ name: string; specialty: string; availability: string }[]> {
    const doctors: { name: string; specialty: string; availability: string }[] = [];
    const cards = await this.doctorCards.all();

    for (const card of cards) {
      const name = await this.getText(this.doctorName(card));
      const specialty = await this.getText(this.doctorSpecialty(card));
      const availability = await this.getText(this.doctorAvailability(card));
      doctors.push({ name, specialty, availability });
    }
    return doctors;
  }

  /**
   * Verifies that each displayed doctor card has the required information.
   */
  public async verifyDoctorCardDetails(): Promise<void> {
    const cards = await this.doctorCards.all();
    expect(cards.length).toBeGreaterThan(0); // Ensure at least one doctor card is present

    for (const card of cards) {
      await expect(this.doctorName(card)).toBeVisible();
      await expect(this.doctorSpecialty(card)).toBeVisible();
      await expect(this.doctorAvailability(card)).toBeVisible();
      expect(await this.getText(this.doctorName(card))).not.toBe('');
      expect(await this.getText(this.doctorSpecialty(card))).not.toBe('');
      expect(await this.getText(this.doctorAvailability(card))).not.toBe('');
    }
  }

  /**
   * Clicks the 'Book Appointment' button for a specific doctor.
   * Assumes the doctor is visible on the current page.
   * @param doctorName The name of the doctor to book an appointment with.
   */
  public async bookAppointmentForDoctor(doctorName: string): Promise<void> {
    const doctorCard = this.doctorCards.filter({ hasText: doctorName }).first();
    await expect(doctorCard).toBeVisible(); // Ensure the doctor card is visible
    await this.click(this.bookAppointmentButton(doctorCard));
    await this.page.waitForLoadState('networkidle');
  }

  /**
   * Checks for and interacts with pagination if present.
   * @returns A Promise that resolves to true if pagination is handled, false otherwise.
   */
  public async checkPagination(): Promise<boolean> {
    if (await this.paginationNextButton.isVisible()) {
      console.log('Pagination detected. Clicking next page.');
      await this.click(this.paginationNextButton);
      await this.page.waitForLoadState('networkidle');
      await expect(this.doctorCards).toHaveCount(expect.toBeGreaterThan(0)); // Ensure new doctors are loaded
      return true;
    }
    return false;
  }
}
```

