### File: `playwright.config.ts`

This is the main Playwright configuration file, defining how tests are run, reporters, timeouts, and browser configurations. It's set up for single-worker execution with robust error tracing and screenshot/video capture on failure.

```typescript
import { defineConfig, devices } from '@playwright/test';
import { EnvUtils } from './utils/envUtils';
import path from 'path';

const runId = new Date().getTime(); // Unique run ID for output folders

export default defineConfig({
  testDir: './tests',
  // Folder for test artifacts such as screenshots, videos, and traces.
  outputDir: 'test-results/run-' + runId,

  // Run tests in files in parallel
  fullyParallel: false,
  // Limit the number of workers to 1 for stability in potentially stateful tests
  workers: 1,
  // Do not retry tests on CI
  retries: 0,

  // Reporter to use. See https://playwright.dev/docs/test-reporters
  reporter: [['html', { outputFolder: 'playwright-report/run-' + runId }]],

  // Shared settings for all the projects below. See https://playwright.dev/docs/api/class-testoptions.
  globalTimeout: 180000, // Global timeout for the entire test run (180 seconds)
  expect: {
    timeout: 60000, // Timeout for expect assertions (60 seconds)
  },

  use: {
    // Base URL to use in actions like `await page.goto('/')`.
    baseURL: EnvUtils.BASE_URL,
    // Action timeout for all Playwright actions (e.g., click, fill).
    actionTimeout: 50000, // 50 seconds
    // Collect trace when retrying the failed test. See https://playwright.dev/docs/trace-viewer
    trace: 'on',
    // Capture screenshot on test failure.
    screenshot: 'only-on-failure',
    // Record video on test failure.
    video: 'retain-on-failure',
  },

  /* Configure projects for major browsers */
  projects: [
    {
      name: 'chromium',
      use: { 
        ...devices['Desktop Chrome'],
        // No storageState or dependencies: ['setup'] as no authentication/login steps are required
        // for the provided test cases.
      },
    },
    // Other projects (e.g., 'firefox', 'webkit') can be added here if needed
  ],
});
