## --- Page Object Model (POM)

### File: `pages/BasePage.ts`

The `BasePage` class provides a foundation for all page objects, including common methods for interaction, waiting, and assertions. This promotes reusability and maintains a consistent approach across the framework.

```typescript
import { expect, Locator, Page } from '@playwright/test';

/**
 * Abstract base class for all Page Objects.
 * Provides common functionalities and a reference to the Playwright Page object.
 */
export abstract class BasePage {
    /**
     * The Playwright Page object associated with this Page Object.
     * @type {Page}
     */
    public readonly page: Page;

    /**
     * Constructor for BasePage.
     * @param page The Playwright Page object.
     */
    constructor(page: Page) {
        this.page = page;
    }

    /**
     * Navigates the browser to the specified URL.
     * @param url The URL to navigate to.
     */
    public async navigate(url: string): Promise<void> {
        await this.page.goto(url);
    }

    /**
     * Waits for an element to be visible.
     * @param locator The Playwright Locator for the element.
     * @param timeout Optional timeout in milliseconds. Defaults to 10000ms.
     */
    public async waitForVisible(locator: Locator, timeout?: number): Promise<void> {
        await expect(locator).toBeVisible({ timeout: timeout ?? 10000 });
    }

    /**
     * Waits for an element to be enabled.
     * @param locator The Playwright Locator for the element.
     * @param timeout Optional timeout in milliseconds. Defaults to 10000ms.
     */
    public async waitForEnabled(locator: Locator, timeout?: number): Promise<void> {
        await expect(locator).toBeEnabled({ timeout: timeout ?? 10000 });
    }

    /**
     * Clicks on an element after waiting for it to be visible and enabled.
     * @param locator The Playwright Locator for the element.
     */
    public async clickElement(locator: Locator): Promise<void> {
        await this.waitForVisible(locator);
        await this.waitForEnabled(locator);
        await locator.click();
    }

    /**
     * Fills a text input field after waiting for it to be visible and enabled.
     * @param locator The Playwright Locator for the input field.
     * @param value The text value to fill.
     */
    public async fillInput(locator: Locator, value: string): Promise<void> {
        await this.waitForVisible(locator);
        await this.waitForEnabled(locator);
        await locator.fill(value);
    }

    /**
     * Retrieves the text content of an element.
     * @param locator The Playwright Locator for the element.
     * @returns A promise that resolves to the text content or an empty string if not found.
     */
    public async getText(locator: Locator): Promise<string> {
        await this.waitForVisible(locator);
        return (await locator.textContent()) || '';
    }

    /**
     * Retrieves the value of an input element.
     * @param locator The Playwright Locator for the input element.
     * @returns A promise that resolves to the input value or an empty string if not found.
     */
    public async getInputValue(locator: Locator): Promise<string> {
        await this.waitForVisible(locator);
        return (await locator.inputValue()) || '';
    }
}
```

### File: `pages/PatientLedgerPage.ts`

This Page Object encapsulates the interactions with the patient's financial ledger and the UI sections that display email notifications within the application. It provides methods to navigate, retrieve financial details, and verify email content.

```typescript
import { expect, Locator, Page } from '@playwright/test';
import { BasePage } from './BasePage';
import { EnvUtils } from '../utils/envUtils';

/**
 * Page Object for the Patient Ledger and related notification views.
 * Handles interactions with patient financial summaries and email audit UIs.
 */
export class PatientLedgerPage extends BasePage {
    // Locators for Patient Ledger elements
    public readonly patientLedgerTitle: Locator;
    public readonly outstandingBalanceText: Locator;
    public readonly ledgerStatusText: Locator;

    // Locators for Email Notification display (assuming there's a UI to view sent emails within the app)
    public readonly notificationsTab: Locator;
    public readonly emailNotificationItem: Locator; // A specific email notification in a list
    public readonly emailSubjectDetail: Locator;
    public readonly emailBodyContent: Locator;
    public readonly paymentPortalLinkInEmail: Locator;

    /**
     * Initializes the PatientLedgerPage with the Playwright Page object.
     * @param page The Playwright Page object.
     */
    constructor(page: Page) {
        super(page);
        this.patientLedgerTitle = page.getByRole('heading', { name: 'Patient Financial Ledger' });
        this.outstandingBalanceText = page.getByTestId('patient-balance-amount');
        this.ledgerStatusText = page.getByTestId('patient-balance-status');

        this.notificationsTab = page.getByRole('tab', { name: 'Notifications' });
        // Locator for a specific email notification item in a list.
        // Assumes a notification exists with "Payment Due" in its summary/title.
        this.emailNotificationItem = page.getByRole('listitem').filter({ hasText: 'Your Recent Visit - Payment Due' });
        this.emailSubjectDetail = page.getByTestId('email-detail-subject');
        this.emailBodyContent = page.getByTestId('email-detail-body');
        this.paymentPortalLinkInEmail = page.getByRole('link', { name: 'payment portal' });
    }

    /**
     * Navigates to the patient's financial ledger page.
     * Assumes a URL structure like /patients/{patientId}/ledger.
     * @param patientId The ID of the patient whose ledger is to be viewed.
     */
    public async navigateToPatientLedger(patientId: string): Promise<void> {
        await this.page.goto(`${EnvUtils.BASE_URL}/patients/${patientId}/ledger`);
        await this.waitForVisible(this.patientLedgerTitle); // Wait for the ledger page title to be visible
    }

    /**
     * Retrieves the displayed outstanding balance.
     * @returns The outstanding balance as a string.
     */
    public async getOutstandingBalance(): Promise<string> {
        return await this.getText(this.outstandingBalanceText);
    }

    /**
     * Retrieves the displayed ledger status for the outstanding balance.
     * @returns The ledger status as a string.
     */
    public async getLedgerStatus(): Promise<string> {
        return await this.getText(this.ledgerStatusText);
    }

    /**
     * Navigates to the notifications tab to view sent emails.
     */
    public async navigateToNotifications(): Promise<void> {
        await this.clickElement(this.notificationsTab);
        await this.waitForVisible(this.emailNotificationItem.first()); // Wait for at least one notification item
    }

    /**
     * Selects and opens a specific email notification item to view its details.
     * @param emailSubject The subject of the email to open.
     */
    public async openEmailNotification(emailSubject: string): Promise<void> {
        const specificEmail = this.page.getByRole('listitem').filter({ hasText: emailSubject }).first();
        await this.clickElement(specificEmail);
        await this.waitForVisible(this.emailSubjectDetail); // Wait for the email detail view to load
    }

    /**
     * Verifies the subject of the displayed email notification.
     * @param expectedSubject The expected subject of the email.
     */
    public async verifyEmailSubject(expectedSubject: string): Promise<void> {
        await expect(this.emailSubjectDetail).toHaveText(expectedSubject);
    }

    /**
     * Verifies the content of the displayed email notification body for specific text.
     * @param expectedName The expected patient name in the email body.
     * @param expectedBalance The expected balance due in the email body.
     */
    public async verifyEmailBodyContent(expectedName: string, expectedBalance: string): Promise<void> {
        await expect(this.emailBodyContent).toContainText(expectedName);
        await expect(this.emailBodyContent).toContainText(expectedBalance);
    }

    /**
     * Retrieves the URL of the payment portal link from the email body.
     * @returns The href attribute of the payment portal link.
     */
    public async getPaymentPortalLinkUrl(): Promise<string | null> {
        await this.waitForVisible(this.paymentPortalLinkInEmail);
        return await this.paymentPortalLinkInEmail.getAttribute('href');
    }

    /**
     * Clicks the payment portal link within the email.
     */
    public async clickPaymentPortalLink(): Promise<void> {
        await this.clickElement(this.paymentPortalLinkInEmail);
        await this.page.waitForLoadState('domcontentloaded'); // Wait for the new page to load
    }
}
