## --- Page Object Model (POM)

### File: `pages/BasePage.ts`

An abstract base class for all Page Objects, providing common functionalities and enforcing a consistent structure.

```typescript
import { expect, Locator, Page } from '@playwright/test';

/**
 * Abstract BasePage class to encapsulate common page interactions and properties.
 * All specific page objects should extend this class.
 */
export abstract class BasePage {
    /**
     * The Playwright Page object, representing the browser tab.
     * @type {Page}
     */
    public readonly page: Page;

    /**
     * Initializes a new instance of the BasePage.
     * @param page The Playwright Page object.
     */
    constructor(page: Page) {
        this.page = page;
    }

    /**
     * Navigates the page to a specified URL.
     * @param url The URL string to navigate to.
     */
    public async navigateTo(url: string): Promise<void> {
        await this.page.goto(url);
    }

    /**
     * Clicks on a given Playwright Locator.
     * @param locator The Locator object to click.
     * @param timeout Optional timeout in milliseconds for the click action. Defaults to Playwright's actionTimeout if not specified.
     */
    public async click(locator: Locator, timeout?: number): Promise<void> {
        await locator.click({ timeout });
    }

    /**
     * Fills a text input field with the specified text.
     * This method is preferred over `type()` as it simulates user input more accurately for forms.
     * @param locator The Locator object of the input field.
     * @param text The text string to fill into the input field.
     * @param timeout Optional timeout in milliseconds for the fill action.
     */
    public async fill(locator: Locator, text: string, timeout?: number): Promise<void> {
        await locator.fill(text, { timeout });
    }

    /**
     * Retrieves the text content of a given Locator.
     * @param locator The Locator object to retrieve text from.
     * @returns A Promise that resolves to the trimmed text content, or an empty string if no content.
     */
    public async getText(locator: Locator): Promise<string> {
        return (await locator.textContent())?.trim() || '';
    }

    /**
     * Checks if a locator is visible within the viewport.
     * @param locator The Locator object to check.
     * @param timeout Optional timeout in milliseconds to wait for visibility. Defaults to 10000ms.
     * @returns A Promise that resolves to true if the locator is visible, false otherwise.
     */
    public async isVisible(locator: Locator, timeout?: number): Promise<boolean> {
        try {
            await expect(locator).toBeVisible({ timeout: timeout ?? 10000 });
            return true;
        } catch (error) {
            return false;
        }
    }

    /**
     * Waits for a locator to become enabled.
     * @param locator The Locator object to wait for.
     * @param timeout Optional timeout in milliseconds. Defaults to 10000ms.
     */
    public async waitForEnabled(locator: Locator, timeout?: number): Promise<void> {
        await expect(locator).toBeEnabled({ timeout: timeout ?? 10000 });
    }

    /**
     * Waits for a locator to become disabled.
     * @param locator The Locator object to wait for.
     * @param timeout Optional timeout in milliseconds. Defaults to 10000ms.
     */
    public async waitForDisabled(locator: Locator, timeout?: number): Promise<void> {
        await expect(locator).toBeDisabled({ timeout: timeout ?? 10000 });
    }

    /**
     * Waits for a locator to disappear from the DOM or become hidden.
     * @param locator The Locator object to wait for.
     * @param timeout Optional timeout in milliseconds. Defaults to 10000ms.
     */
    public async waitForHidden(locator: Locator, timeout?: number): Promise<void> {
        await expect(locator).toBeHidden({ timeout: timeout ?? 10000 });
    }
}
