import { Locator, Page } from '@playwright/test';
import { BasePage } from './BasePage';

/**
 * Page Object for the Patient Dashboard and Doctor List functionality.
 */
export class PatientDashboardPage extends BasePage {
    // Locators
    public readonly dashboardHeader: Locator;
    public readonly findADoctorLink: Locator;
    public readonly doctorListContainer: Locator;
    public readonly doctorName: (name: string) => Locator;
    public readonly doctorSpecialty: (name: string) => Locator;
    public readonly doctorAvailability: (name: string) => Locator;
    public readonly noDoctorsFoundMessage: Locator;

    /**
     * Initializes a new instance of the PatientDashboardPage.
     * @param page The Playwright Page object.
     */
    constructor(page: Page) {
        super(page);
        this.dashboardHeader = page.getByRole('heading', { name: 'Patient Dashboard' });
        this.findADoctorLink = page.getByRole('link', { name: 'Find a Doctor' });
        this.doctorListContainer = page.locator('[data-test-id="doctor-list-container"]');
        this.noDoctorsFoundMessage = page.getByText('No doctors found.', { exact: true });

        // Dynamic locators for doctor details within the list
        this.doctorName = (name: string) => page.locator(`[data-test-id="doctor-card"]:has-text("${name}")`).getByRole('heading', { name: name, exact: true });
        this.doctorSpecialty = (name: string) => page.locator(`[data-test-id="doctor-card"]:has-text("${name}")`).locator('[data-test-id="doctor-specialty"]');
        this.doctorAvailability = (name: string) => page.locator(`[data-test-id="doctor-card"]:has-text("${name}")`).locator('[data-test-id="doctor-availability"]');
    }

    /**
     * Verifies that the patient dashboard is loaded and visible.
     */
    public async verifyDashboardLoaded(): Promise<void> {
        await this.isVisible(this.dashboardHeader, 15000); // Increased timeout for initial page load
    }

    /**
     * Clicks on the "Find a Doctor" link to navigate to the doctor listing.
     */
    public async clickFindADoctor(): Promise<void> {
        await this.click(this.findADoctorLink);
        // Optionally wait for the next page/section to load or doctor list container to be visible
        await this.isVisible(this.doctorListContainer);
    }

    /**
     * Verifies that the doctor list container is displayed and contains doctors.
     * @returns A Promise that resolves to true if the list is visible and not empty.
     */
    public async verifyDoctorListDisplayed(): Promise<boolean> {
        // Wait for the container to be visible
        await this.isVisible(this.doctorListContainer);
        // Ensure it contains at least one doctor card element
        const doctorCards = await this.page.locator('[data-test-id="doctor-card"]').count();
        return doctorCards > 0;
    }

    /**
     * Verifies the details of a specific doctor card.
     * @param doctorName The name of the doctor to verify.
     * @param specialty The expected specialty of the doctor.
     * @param availabilityStatus The expected availability status of the doctor.
     */
    public async verifyDoctorDetails(doctorName: string, specialty: string, availabilityStatus: string): Promise<void> {
        await this.isVisible(this.doctorName(doctorName));
        await this.page.waitForFunction(
            ({ locator, expectedSpecialty, expectedAvailability }) => {
                const element = document.querySelector(`[data-test-id="doctor-card"]:has-text("${locator}")`);
                if (element) {
                    const specialtyText = element.querySelector('[data-test-id="doctor-specialty"]')?.textContent;
                    const availabilityText = element.querySelector('[data-test-id="doctor-availability"]')?.textContent;
                    return specialtyText?.includes(expectedSpecialty) && availabilityText?.includes(expectedAvailability);
                }
                return false;
            },
            { locator: doctorName, expectedSpecialty: specialty, expectedAvailability: availabilityStatus }
        );
    }
}
