import { expect, Locator, Page } from '@playwright/test';
import { BasePage } from './BasePage';

/**
 * Page Object for the Appointment Booking Page.
 * Handles selecting appointment details, confirming, and verifying booking.
 */
export class AppointmentPage extends BasePage {
  public readonly doctorNameHeader: Locator;
  public readonly dateInput: Locator;
  public readonly timeDropdown: Locator;
  public readonly reasonForVisitTextarea: Locator;
  public readonly confirmAppointmentButton: Locator;
  public readonly appointmentConfirmationMessage: Locator;
  public readonly backToDashboardButton: Locator;

  /**
   * Constructor for AppointmentPage.
   * @param page The Playwright Page object.
   */
  constructor(page: Page) {
    super(page);
    this.doctorNameHeader = page.getByRole('heading', { level: 2, name: /Dr\./i }); // Assumes doctor's name is a header
    this.dateInput = page.getByLabel('Appointment Date');
    this.timeDropdown = page.getByLabel('Appointment Time');
    this.reasonForVisitTextarea = page.getByLabel('Reason for Visit');
    this.confirmAppointmentButton = page.getByRole('button', { name: 'Confirm Appointment' });
    this.appointmentConfirmationMessage = page.getByText('Appointment Confirmed!', { exact: false }) || page.getByTestId('appointment-confirmation-message');
    this.backToDashboardButton = page.getByRole('button', { name: 'Back to Dashboard' });
  }

  /**
   * Navigates directly to a doctor's booking page.
   * (This might not always be possible in a real app; typically reached from DoctorsPage).
   * @param doctorId The ID or slug of the doctor.
   */
  public async navigateToBookAppointment(doctorId: string): Promise<void> {
    await this.goto(`/doctors/${doctorId}/book`); // Example direct URL
    await this.page.waitForLoadState('networkidle');
    await this.waitForEnabled(this.confirmAppointmentButton);
  }

  /**
   * Selects an appointment date.
   * @param date The date string to enter (e.g., '2024-12-25').
   */
  public async selectDate(date: string): Promise<void> {
    await this.fill(this.dateInput, date);
    // Add a potential escape key press to close date pickers if they pop up and block other elements
    await this.page.keyboard.press('Escape');
  }

  /**
   * Selects an appointment time from a dropdown.
   * @param time The time string to select (e.g., '10:00 AM').
   */
  public async selectTime(time: string): Promise<void> {
    await this.selectOption(this.timeDropdown, time);
  }

  /**
   * Enters the reason for the visit into a textarea.
   * @param reason The reason for the visit.
   */
  public async enterReasonForVisit(reason: string): Promise<void> {
    await this.fill(this.reasonForVisitTextarea, reason);
  }

  /**
   * Clicks the button to confirm the appointment.
   */
  public async confirmAppointment(): Promise<void> {
    await this.click(this.confirmAppointmentButton);
    await this.page.waitForLoadState('networkidle');
  }

  /**
   * Checks if the appointment confirmation message is displayed.
   * @returns A Promise that resolves to true if the message is visible, false otherwise.
   */
  public async verifyConfirmationMessageDisplayed(): Promise<boolean> {
    return this.isVisible(this.appointmentConfirmationMessage);
  }

  /**
   * Waits for the appointment confirmation message to appear.
   */
  public async waitForConfirmationMessage(): Promise<void> {
    await expect(this.appointmentConfirmationMessage).toBeVisible({ timeout: 30000 });
  }

  /**
   * Clicks the button to navigate back to the dashboard.
   */
  public async backToDashboard(): Promise<void> {
    await this.click(this.backToDashboardButton);
    await this.page.waitForLoadState('networkidle');
  }
}
