import { test, expect, Page } from '@playwright/test';
import { DashboardPage } from '../pages/DashboardPage';
import { DoctorsPage } from '../pages/DoctorsPage';
import { AppointmentPage } from '../pages/AppointmentPage';
import { EnvUtils } from '../utils/envUtils';

test.describe('Appointment Booking Functionality', () => {

  let dashboardPage: DashboardPage;
  let doctorsPage: DoctorsPage;
  let appointmentPage: AppointmentPage;

  test.beforeEach(async ({ page }) => {
    dashboardPage = new DashboardPage(page);
    doctorsPage = new DoctorsPage(page);
    appointmentPage = new AppointmentPage(page);
    // User is logged in via auth.setup.ts due to 'setup' dependency in playwright.config.ts.
    // Navigating to BASE_URL should land on the dashboard directly.
    await page.goto(EnvUtils.BASE_URL);
    await page.waitForLoadState('networkidle');
    await expect(dashboardPage.welcomeMessage).toBeVisible(); // Ensure dashboard is loaded
  });

  test('TC-EXT-APP-001: Patient successfully books an appointment with a doctor', async ({ page }, testInfo) => {
    // Test data for the appointment booking.
    const testData = {
      doctorName: 'Dr. Emily White', // This doctor should exist in the test environment
      appointmentDate: '2024-12-25', // Format as expected by the UI date input
      appointmentTime: '10:00 AM',   // Format as expected by the UI time dropdown
      reasonForVisit: 'General check-up and annual physical'
    };

    // 1. Navigate to the "Find a Doctor" page from the Dashboard.
    await test.step('Navigate to Find a Doctor page', async () => {
      await dashboardPage.navigateToDoctorList();
      await expect(page).toHaveURL(/doctors|providers/); // Verify URL matches doctor list page
      await doctorsPage.verifyDoctorListDisplayed();
    });

    // 2. Select a specific doctor from the list and proceed to their profile/booking page.
    await test.step(`Select doctor "${testData.doctorName}" and proceed to booking`, async () => {
      // Clicks the 'Book Appointment' button within the specified doctor's card.
      // This method navigates to the booking page after the click.
      await doctorsPage.bookAppointmentForDoctor(testData.doctorName);
      // Verify the URL and that the doctor's name is displayed on the booking page.
      await expect(page).toHaveURL(/doctors\/.+\/book/);
      await expect(appointmentPage.doctorNameHeader).toHaveText(testData.doctorName);
    });

    // 3. Fill in the appointment details (date, time, reason for visit).
    await test.step('Fill in appointment details', async () => {
      await appointmentPage.selectDate(testData.appointmentDate);
      await appointmentPage.selectTime(testData.appointmentTime);
      await appointmentPage.enterReasonForVisit(testData.reasonForVisit);
    });

    // 4. Confirm the appointment by clicking the 'Confirm Appointment' button.
    await test.step('Confirm the appointment', async () => {
      await appointmentPage.confirmAppointment();
    });

    // 5. Verify that an appointment confirmation message is displayed on the screen.
    await test.step('Verify appointment confirmation message', async () => {
      await appointmentPage.waitForConfirmationMessage();
      await expect(appointmentPage.appointmentConfirmationMessage).toBeVisible();
      await expect(appointmentPage.appointmentConfirmationMessage).toHaveText(/Appointment Confirmed!|Successfully Booked/i);
    });

    // 6. Optionally, navigate back to the dashboard to complete the flow.
    await test.step('Navigate back to Dashboard', async () => {
      await appointmentPage.backToDashboard();
      await expect(page).toHaveURL(/dashboard|home/); // Verify navigation back to dashboard
      await expect(dashboardPage.welcomeMessage).toBeVisible(); // Ensure dashboard is loaded
    });
    testInfo.annotations.push({ type: 'Test Case ID', description: 'TC-EXT-APP-001' });
  });
});
