import { Locator, Page, expect } from '@playwright/test';
import { BasePage } from './BasePage';

/**
 * Page Object for the Doctor Search functionality.
 */
export class DoctorSearchPage extends BasePage {
    // Locators
    public readonly doctorSearchField: Locator;
    public readonly searchButton: Locator;
    public readonly searchResultsContainer: Locator;
    public readonly noMatchingResultsMessage: Locator;
    public readonly doctorCard: (name: string) => Locator;

    /**
     * Initializes a new instance of the DoctorSearchPage.
     * @param page The Playwright Page object.
     */
    constructor(page: Page) {
        super(page);
        this.doctorSearchField = page.getByPlaceholder('Enter Doctor Name') || page.getByLabel('Doctor Name Search');
        this.searchButton = page.getByRole('button', { name: 'Search' });
        this.searchResultsContainer = page.locator('[data-test-id="doctor-search-results"]');
        this.noMatchingResultsMessage = page.getByText('No doctors found matching your search criteria');

        // Dynamic locator for a specific doctor card in search results
        this.doctorCard = (name: string) => page.locator(`[data-test-id="doctor-card"]:has-text("${name}")`);
    }

    /**
     * Navigates directly to the Doctor Search page.
     * This assumes a direct URL or a known navigation path from Base URL.
     * For this scenario, we'll assume navigating to the base URL and clicking "Find a Doctor" leads here,
     * or a direct path is provided by EnvUtils.
     */
    public async navigateToDoctorSearchPage(): Promise<void> {
        // Assuming navigation via dashboard, or a direct link might be available.
        // For simplicity, we assume we are already on a page that allows navigation to search,
        // or that it's the target page after clicking "Find a Doctor".
        // If a direct URL existed for doctor search, it would be `await this.navigateTo(EnvUtils.DOCTOR_SEARCH_URL);`
        await this.isVisible(this.doctorSearchField); // Ensure the search page is loaded
    }

    /**
     * Enters a doctor's name into the search field.
     * @param name The full or partial name of the doctor to search for.
     */
    public async enterDoctorName(name: string): Promise<void> {
        await this.fill(this.doctorSearchField, name);
    }

    /**
     * Clicks the search button to initiate the doctor search.
     */
    public async clickSearchButton(): Promise<void> {
        await this.click(this.searchButton);
        await expect(this.searchResultsContainer.or(this.noMatchingResultsMessage)).toBeVisible(); // Wait for results or no results message
    }

    /**
     * Verifies that the search results container is displayed and contains matching doctors.
     * @param expectedDoctorCount The expected number of doctor results. Optional.
     */
    public async verifySearchResultsDisplayed(expectedDoctorCount?: number): Promise<void> {
        await this.isVisible(this.searchResultsContainer);
        await expect(this.noMatchingResultsMessage).toBeHidden();
        if (expectedDoctorCount !== undefined) {
            await expect(this.searchResultsContainer.locator('[data-test-id="doctor-card"]')).toHaveCount(expectedDoctorCount);
        } else {
            // Assert that there is at least one doctor card if count is not specified
            await expect(this.searchResultsContainer.locator('[data-test-id="doctor-card"]').first()).toBeVisible();
        }
    }

    /**
     * Verifies that a specific doctor is present in the search results.
     * @param doctorName The name of the doctor to verify.
     */
    public async verifyDoctorInResults(doctorName: string): Promise<void> {
        await this.isVisible(this.doctorCard(doctorName));
    }

    /**
     * Verifies that no matching results message is displayed.
     */
    public async verifyNoMatchingResultsMessage(): Promise<void> {
        await this.isVisible(this.noMatchingResultsMessage);
        await expect(this.searchResultsContainer).toBeHidden(); // Ensure no results container is visible
    }

    /**
     * Verifies that a validation message is displayed for an empty search query.
     * This method expects a validation message to appear, which might be a different locator
     * than 'noMatchingResultsMessage' for an empty search. Adjust locator as needed.
     */
    public async verifyEmptySearchValidationMessage(): Promise<void> {
        // Assuming a general validation message or the same 'no doctors found' if allowed to search empty
        // In a real application, a specific error for 'empty input' would be handled.
        // For now, if no explicit validation message, we might expect all doctors or 'no doctors found' if strict.
        // Let's assume it displays 'No doctors found' if empty search is treated as no specific criteria.
        await this.isVisible(this.noMatchingResultsMessage); 
        // Or if there's a specific validation message like 'Please enter a search term'
        // await this.isVisible(this.page.getByText('Please enter a search term', { exact: true }));
    }
}
