### File: `tests/auth.setup.ts`

This file handles the authentication process required for subsequent tests. It performs a "Global Login" as per the test case, which implies system-handled authentication on navigation, and saves the session state.

```typescript
import { test, expect, Page } from '@playwright/test';
import { STORAGE_STATE } from '../playwright.config';
import { EnvUtils } from '../utils/envUtils';
import { PatientDashboardPage } from '../pages/PatientDashboardPage';

/**
 * Authentication setup file for Playwright.
 * This test navigates to the base URL, which triggers the "Global Login Context" as per the precondition.
 * It then verifies that the patient dashboard is loaded, indicating successful implicit authentication,
 * and saves the authentication state for reuse in other tests.
 */
test('do global login', async ({ page }: { page: Page }) => {
  const patientDashboardPage = new PatientDashboardPage(page);

  // Step 1 & 2: Navigate to the base URL to trigger "Global Login Context"
  // The precondition implies authentication is handled by the system upon navigating to the base URL,
  // bypassing manual entry of credentials or OTP.
  await page.goto(EnvUtils.BASE_URL);

  // Step 3: Verify that the application successfully authenticates and lands on the Patient Dashboard.
  // We wait for a key element on the dashboard to ensure successful loading and authentication.
  await patientDashboardPage.verifyDashboardLoaded();

  // Save the storage state (cookies, local storage, etc.) after successful login.
  // This state will be used by other test projects to start tests in an authenticated state.
  await page.context().storageState({ path: STORAGE_STATE });
});

