import { expect, Locator, Page } from '@playwright/test';

/**
 * Abstract class representing the Base Page Template for all DOM configurations
 */
export abstract class BasePage {
    public readonly page: Page;

    constructor(page: Page) {
        this.page = page;
    }

    /**
     * Navigates directly to a localized URL path
     */
    public async navigateTo(path: string = ''): Promise<void> {
        await this.page.goto(path, { waitUntil: 'domcontentloaded' });
    }

    /**
     * Safely grabs text content from a Locator
     */
    public async getText(locator: Locator): Promise<string> {
        return (await locator.textContent()) || '';
    }

    /**
     * Wrapper validation method enforcing element visibility/state
     */
    public async waitForEnabled(locator: Locator, timeout?: number): Promise<void> {
        await expect(locator).toBeEnabled({ timeout: timeout ?? 10000 });
    }
}
