import { expect, Locator, Page } from '@playwright/test';
import { BasePage } from './BasePage';

export class HomePage extends BasePage {
    // Navigation Locators
    public readonly productsMenu: Locator;
    public readonly solutionsMenu: Locator;
    public readonly resourcesMenu: Locator;
    public readonly platformMenu: Locator;

    // Submenu links
    public readonly itServiceManagementLink: Locator;
    public readonly customerWorkflowsLink: Locator;
    public readonly resourceLibraryLink: Locator;

    // Global Search Header Controls
    public readonly searchTriggerButton: Locator;
    public readonly searchInputField: Locator;

    // Responsive/Mobile Layout Elements
    public readonly mobileHamburgerMenu: Locator;
    public readonly mobilePlatformLink: Locator;

    // Localization & Footer Locators
    public readonly footerSection: Locator;
    public readonly officeAddressBangalore: Locator;
    public readonly officeAddressHyderabad: Locator;
    public readonly officeAddressMumbai: Locator;
    public readonly promotionBanners: Locator;
    public readonly timezoneEventTimes: Locator;

    constructor(page: Page) {
        super(page);

        // Navigation Menus using strict Locator Strategy (getByRole, getByLabel, testId)
        this.productsMenu = this.page.getByRole('button', { name: 'Products', exact: true });
        this.solutionsMenu = this.page.getByRole('button', { name: 'Solutions', exact: true });
        this.resourcesMenu = this.page.getByRole('button', { name: 'Resources', exact: true });
        this.platformMenu = this.page.getByRole('button', { name: 'Platform', exact: true });

        // Navigation Submenu Links
        this.itServiceManagementLink = this.page.getByRole('link', { name: 'IT Service Management', exact: true });
        this.customerWorkflowsLink = this.page.getByRole('link', { name: 'Customer Workflows', exact: true });
        this.resourceLibraryLink = this.page.getByRole('link', { name: 'Resource Library', exact: true });

        // Search Configuration Locators
        this.searchTriggerButton = this.page.getByRole('button', { name: 'Search', exact: true });
        this.searchInputField = this.page.getByPlaceholder('Search', { exact: true });

        // Mobile Responsive Elements
        this.mobileHamburgerMenu = this.page.getByRole('button', { name: 'Open Navigation Menu', exact: true });
        this.mobilePlatformLink = this.page.getByRole('link', { name: 'Platform', exact: true });

        // Localization Locators
        this.footerSection = this.page.locator('footer');
        this.officeAddressBangalore = this.page.locator('text="Bangalore"');
        this.officeAddressHyderabad = this.page.locator('text="Hyderabad"');
        this.officeAddressMumbai = this.page.locator('text="Mumbai"');
        this.promotionBanners = this.page.locator('.promo-banner-class, .marketing-banner'); 
        this.timezoneEventTimes = this.page.locator('.event-timezone-class, [data-timezone="IST"]');
    }

    public async expandMenu(menuLocator: Locator): Promise<void> {
        await menuLocator.hover();
        await expect(menuLocator).toHaveAttribute('aria-expanded', 'true');
    }

    public async executeSearch(query: string): Promise<void> {
        if (await this.searchTriggerButton.isVisible()) {
            await this.searchTriggerButton.click();
        }
        await this.searchInputField.fill(query);
        await this.page.keyboard.press('Enter');
    }

    public async openHamburgerMenu(): Promise<void> {
        await this.mobileHamburgerMenu.click();
    }
}
