import { expect, Locator, Page } from '@playwright/test';
import { BasePage } from './BasePage';

export class ContactUsPage extends BasePage {
    // Form Inputs
    public readonly nameField: Locator;
    public readonly emailField: Locator;
    public readonly phoneField: Locator;
    public readonly submitButton: Locator;

    // Validation Status Displays
    public readonly thankYouHeader: Locator;
    public readonly nameValidationError: Locator;
    public readonly emailValidationError: Locator;
    public readonly phoneValidationError: Locator;

    constructor(page: Page) {
        super(page);

        // Form controls using strict priority selectors (By Label, Placeholder or ID)
        this.nameField = this.page.getByLabel('Name', { exact: true });
        this.emailField = this.page.getByLabel('Corporate Email', { exact: true });
        this.phoneField = this.page.getByLabel('Phone Number', { exact: true });
        this.submitButton = this.page.getByRole('button', { name: 'Submit', exact: true });

        // Error validation messages and success screens
        this.thankYouHeader = this.page.getByRole('heading', { name: 'Thank You', exact: false });
        this.nameValidationError = this.page.locator('#error-name-field, [data-error="name"]');
        this.emailValidationError = this.page.locator('#error-email-field, [data-error="email"]');
        this.phoneValidationError = this.page.locator('#error-phone-field, [data-error="phone"]');
    }

    public async fillLeadDetails(name: string, email: string, phone: string): Promise<void> {
        if (name !== '') {
            await this.nameField.fill(name);
        } else {
            await this.nameField.clear();
        }

        if (email !== '') {
            await this.emailField.fill(email);
        } else {
            await this.emailField.clear();
        }

        if (phone !== '') {
            await this.phoneField.fill(phone);
        } else {
            await this.phoneField.clear();
        }
    }

    public async submitForm(): Promise<void> {
        await this.submitButton.click();
    }
}
