import { expect, Locator, Page } from '@playwright/test';
import { BasePage } from './BasePage';

export class SearchResultsPage extends BasePage {
    public readonly resultsContainer: Locator;
    public readonly highlightedKeywords: Locator;
    public readonly noResultsMessage: Locator;

    constructor(page: Page) {
        super(page);
        this.resultsContainer = this.page.locator('.search-results-list, #search-results');
        this.highlightedKeywords = this.page.locator('mark, .search-highlight');
        this.noResultsMessage = this.page.locator('.no-results, text="No results found"');
    }

    public async verifyQueryIsHighlighted(query: string): Promise<void> {
        const highlightedElements = this.highlightedKeywords;
        const count = await highlightedElements.count();
        if (count > 0) {
            const textContent = await highlightedElements.first().textContent();
            expect(textContent?.toLowerCase()).toContain(query.toLowerCase());
        }
    }
}
