        await expect(page).toHaveURL(/.*itsm.*/);

        // Navigate back and process Solutions Submenu
        await page.goto(EnvUtils.BASE_URL);
        await homePage.expandMenu(homePage.solutionsMenu);
        await homePage.customerWorkflowsLink.click();
        await expect(page).toHaveURL(/.*customer-workflows.*/);

        // Navigate back and process Resources Submenu
        await page.goto(EnvUtils.BASE_URL);
        await homePage.expandMenu(homePage.resourcesMenu);
        await homePage.resourceLibraryLink.click();
        await expect(page).toHaveURL(/.*resources.*/);
    });

    test('TC-TS-001-002: Verification of Header Menu Navigation Responsiveness and UI Across Resolutions', async ({ page }, testInfo) => {
        const homePage = new HomePage(page);

