        await page.setViewportSize({ width: 768, height: 1024 });
        await homePage.openHamburgerMenu();
        await homePage.mobilePlatformLink.click();
        await expect(page).toHaveURL(/.*platform.*/);
    });

    test('TC-TS-001-003: Resiliency and Rapid Navigation Interaction Robustness Validation', async ({ page }, testInfo) => {
        const homePage = new HomePage(page);

        // Hover sequentially within minimal timelines (Simulating fast switching)
        await homePage.productsMenu.hover();
        await homePage.solutionsMenu.hover();
        await homePage.platformMenu.hover();
        await homePage.resourcesMenu.hover();

        // Rapid Interrupted Click Sequence Strategy
        await homePage.expandMenu(homePage.productsMenu);
        await homePage.itServiceManagementLink.click();

        // Interrupt loading trigger instantly
        await homePage.resourcesMenu.click();
        await expect(page).toHaveURL(/.*resources.*/);
    });
});
