### `playwright.config.ts`

The central configuration file for Playwright, defining test execution settings, reporters, and project-specific configurations.

```typescript
import { defineConfig, devices } from '@playwright/test';
import { EnvUtils } from './utils/envUtils';
import path from 'path';

/**
 * Read environment variables from .env file.
 * For more information, see https://github.com/motdotla/dotenv
 */
// require('dotenv').config(); // Handled by envUtils.ts

const STORAGE_STATE = path.join(__dirname, 'playwright/.auth/user.json');
const runId = new Date().getTime(); // Unique run ID for reporting

/**
 * See https://playwright.dev/docs/test-configuration
 */
export default defineConfig({
  // Directory where tests are located
  testDir: './tests',

  // Output directory for test results and artifacts
  outputDir: 'test-results/run-' + runId,

  // Run tests in files in parallel
  fullyParallel: false,

  // Configure maximum number of workers. Set to 1 for stability in sequential tests.
  workers: 1,

  // Reporter to use. See https://playwright.dev/docs/test-reporters
  reporter: [['html', { outputFolder: 'playwright-report/run-' + runId }]],

  // Shared settings for all the projects below. See https://playwright.dev/docs/api/class-testoptions
  use: {
    // Base URL to use in actions like `await page.goto('/')`.
    baseURL: EnvUtils.BASE_URL,

    // Action timeout for Playwright operations like click, fill, etc.
    actionTimeout: 50000,

    // Collect trace when retrying the first time. See https://playwright.dev/docs/trace-viewer
    trace: 'on',

    // Capture screenshot only on failure
    screenshot: 'only-on-failure',

    // Record video for tests, retaining only on failure
    video: 'retain-on-failure',
  },

  // Configure global timeout for the entire test run
  timeout: 180000, // 3 minutes

  // Configure timeout for expect assertions
  expect: {
    timeout: 60000, // 1 minute
  },

  // Configure retries for tests. Set to 0 to prevent re-execution on failure.
  retries: 0,

  /* Configure projects for major browsers */
  projects: [
    {
      name: 'setup',
      testMatch: /.*\.setup\.ts/, // Matches auth.setup.ts
    },
    {
      name: 'chromium',
      use: {
        ...devices['Desktop Chrome'],
        // Use the authenticated state from the setup project
        storageState: STORAGE_STATE,
      },
      dependencies: ['setup'], // Ensures setup project runs first
      testMatch: /.*\.spec\.ts/, // Matches all spec files
    },
  ],
});
```

