## --- Page Object Model (POM)

### `pages/BasePage.ts`

An abstract base class for all Page Objects, providing common functionalities and properties like the `Page` instance.

```typescript
import { expect, Locator, Page } from '@playwright/test';

/**
 * Abstract BasePage class to provide common functionalities for all Page Objects.
 * All page objects should extend this class.
 */
export abstract class BasePage {
  /**
   * The Playwright Page object instance.
   * @protected
   */
  public readonly page: Page;

  /**
   * Constructs a new BasePage instance.
   * @param page The Playwright Page object.
   */
  constructor(page: Page) {
    this.page = page;
  }

  /**
   * Navigates to a specific URL.
   * @param url The URL to navigate to.
   * @returns A Promise that resolves when the navigation is complete.
   */
  public async navigateTo(url: string): Promise<void> {
    await this.page.goto(url);
  }

  /**
   * Waits for a locator to be visible.
   * @param locator The Locator to wait for.
   * @param timeout Optional timeout in milliseconds. Defaults to 10 seconds.
   * @returns A Promise that resolves when the locator is visible.
   */
  public async waitForVisible(locator: Locator, timeout?: number): Promise<void> {
    await expect(locator).toBeVisible({ timeout: timeout ?? 10000 });
  }

  /**
   * Waits for a locator to be enabled.
   * @param locator The Locator to wait for.
   * @param timeout Optional timeout in milliseconds. Defaults to 10 seconds.
   * @returns A Promise that resolves when the locator is enabled.
   */
  public async waitForEnabled(locator: Locator, timeout?: number): Promise<void> {
    await expect(locator).toBeEnabled({ timeout: timeout ?? 10000 });
  }

  /**
   * Gets the text content of a locator.
   * @param locator The Locator to get text from.
   * @returns A Promise that resolves with the text content as a string.
   */
  public async getText(locator: Locator): Promise<string> {
    return (await locator.textContent()) || '';
  }

  /**
   * Fills an input field with the specified value.
   * @param locator The Locator of the input field.
   * @param value The value to fill into the input field.
   * @returns A Promise that resolves when the fill operation is complete.
   */
  public async fillInput(locator: Locator, value: string): Promise<void> {
    await this.waitForVisible(locator);
    await this.waitForEnabled(locator);
    await locator.fill(value);
  }

  /**
   * Clicks on a locator.
   * @param locator The Locator to click.
   * @returns A Promise that resolves when the click operation is complete.
   */
  public async clickElement(locator: Locator): Promise<void> {
    await this.waitForVisible(locator);
    await this.waitForEnabled(locator);
    await locator.click();
  }
}
```

### `pages/LoginPage.ts`

Page Object for the login functionality, encapsulating locators and actions related to the login page.

```typescript
import { Locator, Page } from '@playwright/test';
import { BasePage } from './BasePage';
import { EnvUtils } from '../utils/envUtils'; // Required for conditional login if credentials not passed

/**
 * LoginPage Page Object representing the login page of the application.
 * Encapsulates login-related elements and actions.
 */
export class LoginPage extends BasePage {
  // Locators for login page elements
  public readonly emailInput: Locator;
  public readonly passwordInput: Locator;
  public readonly loginButton: Locator;

  /**
   * Constructs a new LoginPage instance.
   * @param page The Playwright Page object.
   */
  constructor(page: Page) {
    super(page);
    this.emailInput = page.getByLabel('Email'); // Priority 1: getByLabel
    // Fallback if getByLabel doesn't work: page.getByPlaceholder('Enter your email');
    // Fallback: page.getByTestId('email-input');
    // Fallback: page.locator('#email');

    this.passwordInput = page.getByLabel('Password'); // Priority 1: getByLabel
    // Fallback if getByLabel doesn't work: page.getByPlaceholder('Enter your password');
    // Fallback: page.getByTestId('password-input');
    // Fallback: page.locator('#password');

    this.loginButton = page.getByRole('button', { name: 'Login' }); // Priority 1: getByRole
    // Fallback: page.getByTestId('login-button');
    // Fallback: page.locator('button[type="submit"]');
  }

  /**
   * Navigates to the login page.
   * @returns A Promise that resolves when navigation is complete.
   */
  public async gotoLoginPage(): Promise<void> {
    await this.navigateTo(EnvUtils.BASE_URL);
    await this.waitForVisible(this.loginButton); // Ensure the page is loaded
  }

  /**
   * Performs the login operation with provided credentials.
   * @param email The user's email.
   * @param password The user's password.
   * @returns A Promise that resolves after clicking the login button.
   */
  public async login(email: string, password: string): Promise<void> {
    await this.fillInput(this.emailInput, email);
    await this.fillInput(this.passwordInput, password);
    await this.clickElement(this.loginButton);
    // Add an assertion or wait for redirection if needed
    // await this.page.waitForURL(/dashboard/);
  }
}
```

