## --- Test Implementation

### `tests/auth.setup.ts`

This file handles the authentication flow and saves the user's session state. This allows subsequent tests to run without repeatedly logging in.

```typescript
import { test as setup, expect } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';
import { EnvUtils } from '../utils/envUtils';
import path from 'path';

const STORAGE_STATE = path.join(__dirname, '../playwright/.auth/user.json');

/**
 * This setup test logs in a user and saves their authentication state to a file.
 * This saved state can then be used by other tests to run as an authenticated user,
 * avoiding repeated login steps in each test.
 */
setup('authenticate as a valid user', async ({ page }) => {
  const loginPage = new LoginPage(page);

  // Navigate to the login page
  await loginPage.gotoLoginPage();

  // Perform login using credentials from environment variables
  // IMPORTANT: Use secure process.env variables, DO NOT hardcode credentials.
  await loginPage.login(EnvUtils.TEST_EMAIL, EnvUtils.PASSWORD);

  // Verify successful login by checking for a dashboard element or URL redirection
  // Assuming a successful login redirects to a dashboard or a specific authenticated page
  await expect(page).toHaveURL(/dashboard|home/); // Adjust this regex based on your actual post-login URL
  await expect(page.getByRole('heading', { name: 'Dashboard' })).toBeVisible({ timeout: 15000 }); // Example dashboard element

  // Save the storage state (cookies, local storage, etc.) to reuse in subsequent tests
  await page.context().storageState({ path: STORAGE_STATE });
});
```

### `tests/login.spec.ts`

Test file for verifying login functionality using the pre-authenticated session.

```typescript
import { test, expect, Page } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';
import { EnvUtils } from '../utils/envUtils';

/**
 * Test suite for login functionality.
 */
test.describe('Login Functionality', () => {

  // Before each test in this suite, navigate to the base URL
  test.beforeEach(async ({ page }) => {
    await page.goto(EnvUtils.BASE_URL);
  });

  /**
   * TC-MAN-UP-4306-0: Verify successful login with valid credentials
   * Description: User should be able to log in using a registered email and password.
   * Expected Result: User should be redirected to the dashboard.
   */
  test('Verify successful login with valid credentials', async ({ page }, testInfo) => {
    console.log(`Running test: ${testInfo.title}`);

    // Since 'auth.setup.ts' pre-authenticates the session,
    // this test primarily verifies the authenticated state or can navigate directly to an authenticated page.
    // We can assume the user is already logged in if this test runs after the 'setup' project.

    // To explicitly test login flow, we can re-instantiate LoginPage and navigate.
    // However, the purpose of 'dependencies: ['setup']' is to use the pre-authenticated state.
    // Thus, this test will check if the user is already on the dashboard or can access authenticated content.

    // Example verification that the user is on the dashboard after setup:
    await expect(page).toHaveURL(/dashboard|home/, { timeout: 10000 }); // Adjust based on your actual dashboard URL
    await expect(page.getByRole('heading', { name: 'Dashboard' })).toBeVisible({ timeout: 15000 });

    // Optional: Log out to clean up if necessary for specific test scenarios, though not required by current TC.
    // const dashboardPage = new DashboardPage(page); // Assuming a DashboardPage exists
    // await dashboardPage.logout();
    // await expect(page).toHaveURL(/login/);
  });
});
