```typescript
import * as dotenv from 'dotenv';

// Load environment variables from .env file
dotenv.config();

/**
 * Utility class to access environment variables.
 * Provides a centralized and type-safe way to get configuration values.
 */
export class EnvUtils {
  /**
   * The base URL of the application under test.
   * Fetched from the BASE_URL environment variable. Defaults to an empty string if not set.
   */
  public static readonly BASE_URL: string = process.env.BASE_URL || '';

  /**
   * The test user's email address for authentication.
   * Fetched from the TEST_EMAIL environment variable. Defaults to an empty string if not set.
   * IMPORTANT: This should be treated as sensitive data and never hardcoded.
   */
  public static readonly TEST_EMAIL: string = process.env.TEST_EMAIL || '';

  /**
