## --- Page Object Model (POM)

### `pages/BasePage.ts`

An abstract base class for all Page Objects, providing common functionalities and properties like the `Page` instance.

```typescript
import { expect, Locator, Page } from '@playwright/test';

/**
 * Abstract BasePage class to provide common functionalities for all Page Objects.
 * All page objects should extend this class.
 */
export abstract class BasePage {
  /**
   * The Playwright Page object instance.
   * @protected
   */
  public readonly page: Page;

  /**
   * Constructs a new BasePage instance.
   * @param page The Playwright Page object.
   */
  constructor(page: Page) {
    this.page = page;
  }

  /**
   * Navigates to a specific URL.
   * @param url The URL to navigate to.
   * @returns A Promise that resolves when the navigation is complete.
   */
  public async navigateTo(url: string): Promise<void> {
    await this.page.goto(url);
  }

  /**
   * Waits for a locator to be visible.
   * @param locator The Locator to wait for.
   * @param timeout Optional timeout in milliseconds. Defaults to 10 seconds.
   * @returns A Promise that resolves when the locator is visible.
   */
  public async waitForVisible(locator: Locator, timeout?: number): Promise<void> {
    await expect(locator).toBeVisible({ timeout: timeout ?? 10000 });
  }

  /**
   * Waits for a locator to be enabled.
   * @param locator The Locator to wait for.
   * @param timeout Optional timeout in milliseconds. Defaults to 10 seconds.
   * @returns A Promise that resolves when the locator is enabled.
   */
  public async waitForEnabled(locator: Locator, timeout?: number): Promise<void> {
    await expect(locator).toBeEnabled({ timeout: timeout ?? 10000 });
  }

  /**
   * Gets the text content of a locator.
   * @param locator The Locator to get text from.
   * @returns A Promise that resolves with the text content as a string.
   */
  public async getText(locator: Locator): Promise<string> {
    return (await locator.textContent()) || '';
  }

  /**
   * Fills an input field with the specified value.
   * @param locator The Locator of the input field.
   * @param value The value to fill into the input field.
   * @returns A Promise that resolves when the fill operation is complete.
   */
  public async fillInput(locator: Locator, value: string): Promise<void> {
    await this.waitForVisible(locator);
    await this.waitForEnabled(locator);
    await locator.fill(value);
  }

  /**
   * Clicks on a locator.
   * @param locator The Locator to click.
   * @returns A Promise that resolves when the click operation is complete.
   */
  public async clickElement(locator: Locator): Promise<void> {
    await this.waitForVisible(locator);
    await this.waitForEnabled(locator);
    await locator.click();
  }
}
```

