## File: pages/BasePage.ts

The `BasePage` provides common functionalities and properties for all Page Objects, promoting code reusability and maintainability.

```typescript
import { expect, Locator, Page } from '@playwright/test';

/**
 * Abstract base class for all Page Objects.
 * Provides common functionalities like waiting for elements, navigation, etc.
 */
export abstract class BasePage {
    /**
     * The Playwright Page object instance.
     * @type {Page}
     */
    public readonly page: Page;

    /**
     * Constructor for BasePage.
     * @param {Page} page The Playwright Page object.
     */
    constructor(page: Page) {
        this.page = page;
    }

    /**
     * Navigates to a specified URL relative to the base URL.
     * @param {string} url The URL path to navigate to.
     * @returns {Promise<void>}
     */
    public async navigateTo(url: string): Promise<void> {
        await this.page.goto(url);
    }

    /**
     * Clicks on a given locator and waits for the navigation to complete or an element to become visible.
     * @param {Locator} locator The Playwright Locator to click.
     * @param {Locator | null} [waitAfterClickLocator=null] An optional locator to wait for visibility after clicking.
     * @returns {Promise<void>}
     */
    public async clickElement(locator: Locator, waitAfterClickLocator: Locator | null = null): Promise<void> {
        await this.waitForEnabled(locator);
        await locator.click();
        if (waitAfterClickLocator) {
            await this.waitForVisible(waitAfterClickLocator);
        }
    }

    /**
     * Fills a text input field with the specified value.
     * @param {Locator} locator The Playwright Locator for the input field.
     * @param {string} value The text value to fill.
     * @returns {Promise<void>}
     */
    public async fillInputField(locator: Locator, value: string): Promise<void> {
        await this.waitForVisible(locator);
        await locator.fill(value);
    }

    /**
     * Selects an option from a dropdown by its value, label, or index.
     * @param {Locator} locator The Playwright Locator for the select element.
     * @param {string | string[] | { index?: number; label?: string; value?: string; }} option The option to select.
     * @returns {Promise<void>}
     */
    public async selectOption(locator: Locator, option: string | string[] | { index?: number; label?: string; value?: string; }): Promise<void> {
        await this.waitForVisible(locator);
        await locator.selectOption(option);
    }

    /**
     * Waits for a locator to be visible on the page.
     * @param {Locator} locator The Playwright Locator to wait for.
     * @param {number} [timeout] Optional timeout in milliseconds. Defaults to 10000ms.
     * @returns {Promise<void>}
     */
    public async waitForVisible(locator: Locator, timeout?: number): Promise<void> {
        await expect(locator).toBeVisible({ timeout: timeout ?? 10000 });
    }

    /**
     * Waits for a locator to be enabled on the page.
     * @param {Locator} locator The Playwright Locator to wait for.
     * @param {number} [timeout] Optional timeout in milliseconds. Defaults to 10000ms.
     * @returns {Promise<void>}
     */
    public async waitForEnabled(locator: Locator, timeout?: number): Promise<void> {
        await expect(locator).toBeEnabled({ timeout: timeout ?? 10000 });
    }

    /**
     * Waits for a locator to be hidden or removed from the DOM.
     * @param {Locator} locator The Playwright Locator to wait for.
     * @param {number} [timeout] Optional timeout in milliseconds. Defaults to 10000ms.
     * @returns {Promise<void>}
     */
    public async waitForHidden(locator: Locator, timeout?: number): Promise<void> {
        await expect(locator).toBeHidden({ timeout: timeout ?? 10000 });
    }

    /**
     * Gets the text content of an element.
     * @param {Locator} locator The Playwright Locator.
     * @returns {Promise<string>} The text content, or an empty string if not found.
     */
    public async getText(locator: Locator): Promise<string> {
        await this.waitForVisible(locator);
        return (await locator.textContent()) || '';
    }

    /**
     * Gets the value of an input element.
     * @param {Locator} locator The Playwright Locator.
     * @returns {Promise<string>} The input value, or an empty string if not found.
     */
    public async getInputValue(locator: Locator): Promise<string> {
        await this.waitForVisible(locator);
        return (await locator.inputValue()) || '';
    }
}
