import { EnvUtils } from '../utils/envUtils';
import path from 'path';

// Define the path for storing authentication state
const STORAGE_STATE = path.join(__dirname, '../playwright/.auth/user.json');

/**
 * Authentication setup test.
 * This test logs in a user and saves the authentication state for subsequent tests.
 */
setup('authenticate as test user', async ({ page }) => {
    const loginPage = new LoginPage(page);

    // Navigate to the base URL (which should redirect to login if not already there, or explicitly go to login)
    await page.goto(EnvUtils.BASE_URL);
    await loginPage.gotoLoginPage();

    // Perform login using credentials from environment variables
    await loginPage.login(EnvUtils.TEST_EMAIL, EnvUtils.PASSWORD);

    // Verify successful login by checking for a dashboard element or URL change
    await loginPage.verifyLoginSuccess();

    // Save the authentication state to a file
    // This allows other tests to start with an authenticated session
    await page.context().storageState({ path: STORAGE_STATE });
});
