        this.disabilityTypeDropdown = page.getByLabel('Disability Type', { exact: true });
        this.disabilityPercentageInput = page.getByLabel('Disability Percentage', { exact: true });
        this.certificateIssueDateInput = page.getByLabel('Certificate Issue Date', { exact: true });
        this.certificateExpiryDateInput = page.getByLabel('Certificate Expiry Date', { exact: true });
        this.saveButton = page.getByRole('button', { name: 'Save' }).or(page.getByRole('button', { name: 'Submit' }));
