     * Fills out the new disability record form.
     * @param {string} type The disability type.
     * @param {string} percentage The disability percentage.
     * @param {string} issueDate The certificate issue date (YYYY-MM-DD).
     * @param {string} expiryDate The certificate expiry date (YYYY-MM-DD).
     * @returns {Promise<void>}
     */
    public async fillDisabilityForm(type: string, percentage: string, issueDate: string, expiryDate: string): Promise<void> {
        await this.selectOption(this.disabilityTypeDropdown, { label: type });
        await this.fillInputField(this.disabilityPercentageInput, percentage);
        await this.fillInputField(this.certificateIssueDateInput, issueDate);
        await this.fillInputField(this.certificateExpiryDateInput, expiryDate);
    }

    /**
     * Clicks the 'Save' button to submit the disability record.
     * @returns {Promise<void>}
     */
    public async saveDisabilityRecord(): Promise<void> {
        await this.clickElement(this.saveButton);
    }

    /**
     * Verifies that a success message is displayed after adding a record.
     * @returns {Promise<void>}
     */
    public async verifySuccessMessage(): Promise<void> {
        await this.waitForVisible(this.successMessage);
        await expect(this.successMessage).toBeVisible();
    }

    /**
     * Verifies that the newly added disability record is displayed in the table.
     * @param {string} type The disability type to verify.
     * @param {string} percentage The disability percentage to verify.
     * @param {string} issueDate The certificate issue date to verify.
     * @param {string} expiryDate The certificate expiry date to verify.
     * @returns {Promise<void>}
     */
    public async verifyDisabilityRecordDisplayed(type: string, percentage: string, issueDate: string, expiryDate: string): Promise<void> {
        const recordRow = this.disabilityRecordsTable.locator('tr', { hasText: type })
                                                .filter({ hasText: percentage })
                                                .filter({ hasText: issueDate })
                                                .filter({ hasText: expiryDate });
        await this.waitForVisible(recordRow);
        await expect(recordRow).toBeVisible();
    }
}
