### `tests/auth.setup.js`

Handles the authentication flow once and saves the storage state, allowing all subsequent tests to start from an authenticated state without repeated logins.

```javascript
const { test, expect } = require('@playwright/test');
const LoginPage = require('../pages/LoginPage');
const EnvUtils = require('../utils/envUtils'); // Mandatory import
const path = require('path');

// Define the path for storing authentication state
const STORAGE_STATE = path.join(__dirname, '../playwright/.auth/user.json');

/**
 * @file auth.setup.js
 * @description Playwright setup file for handling user authentication.
 *              It performs a login and saves the browser's storage state.
 *              Subsequent tests can then load this state to start authenticated.
 */
test('perform login and save storage state', async ({ page }) => {
  const loginPage = new LoginPage(page);

  console.log('Starting authentication setup...');

  // Navigate to the base URL or login page
  await page.goto(EnvUtils.BASE_URL);

  // Perform login using credentials from environment variables
  await loginPage.login(EnvUtils.TEST_EMAIL, EnvUtils.TEST_PASSWORD);

  // Verify successful login by checking for a dashboard element or URL
  await expect(page).toHaveURL(/.*dashboard/);
  console.log('Successfully logged in. Current URL:', page.url());

  // Save the storage state (cookies, local storage) to a file
  // This file will be used by other test projects to bypass login
  await page.context().storageState({ path: STORAGE_STATE });
  console.log(`Storage state saved to: ${STORAGE_STATE}`);

  console.log('Authentication setup complete.');
});
