```javascript
/**
 * BasePage.js
 * An abstract base class for all Page Objects, providing common interactions and utilities.
 */
class BasePage {
  /**
   * Navigates to a specific URL.
   * @param {string} url - The URL to navigate to. If relative, it's appended to baseUrl.
   */
  visit(url = '/') {
    cy.visit(url);
  }

  /**
   * Clicks on a web element.
   * @param {string} selector - The CSS selector or data-testid of the element to click.
   */
  clickElement(selector) {
    cy.get(selector).should('be.visible').click();
  }

  /**
   * Types text into an input field.
   * @param {string} selector - The CSS selector or data-testid of the input field.
   * @param {string} text - The text to type.
   */
  typeText(selector, text) {
    cy.get(selector).should('be.visible').clear().type(text);
  }

  /**
   * Verifies if an element contains specific text.
   * @param {string} selector - The CSS selector or data-testid of the element.
   * @param {string} expectedText - The text expected to be in the element.
   */
  shouldContainText(selector, expectedText) {
    cy.get(selector).should('be.visible').and('contain.text', expectedText);
  }

  /**
   * Verifies if an element is visible.
   * @param {string} selector - The CSS selector or data-testid of the element.
   */
  shouldBeVisible(selector) {
    cy.get(selector).should('be.visible');
  }

  /**
   * Gets the text content of an element.
   * @param {string} selector - The CSS selector or data-testid of the element.
   * @returns {Cypress.Chainable<string>} A Cypress chainable that resolves to the element's text.
   */
  getText(selector) {
    return cy.get(selector).should('be.visible').invoke('text');
  }

  /**
   * Uploads a file to an input element.
   * @param {string} selector - The CSS selector or data-testid of the file input element.
   * @param {string} fileName - The name of the file in the `cypress/fixtures` directory.
   * @param {string} mimeType - The MIME type of the file (e.g., 'application/pdf', 'text/plain').
   */
  uploadFile(selector, fileName, mimeType) {
    cy.fixture(fileName, 'binary').then((fileContent) => {
      cy.get(selector).attachFile({
        fileContent: fileContent.toString(),
        fileName: fileName,
        mimeType: mimeType,
        encoding: 'binary',
      });
    });
  }

  /**
   * Waits for a network request to complete.
   * @param {string} alias - The alias set for the request using cy.intercept().
   * @param {number} timeout - Optional timeout in milliseconds.
   */
  waitForRequest(alias, timeout = 30000) {
    cy.wait(alias, { timeout: timeout });
  }
}

module.exports = BasePage;
```

