const BasePage = require('./BasePage');

/**
 * ModulesPage class extends BasePage for interacting with the modules listing and sorting.
 */
class ModulesPage extends BasePage {
  constructor() {
    super();
    this.modulesNav = '[data-testid="nav-modules"]';
    this.sortButton = '[data-testid="sort-button"]';
    this.sortByNameAscendingOption = '[data-testid="sort-option-name-asc"]';
    this.sortByNameDescendingOption = '[data-testid="sort-option-name-desc"]';
    this.sortByCreationDateNewestOption = '[data-testid="sort-option-date-newest"]';
    this.sortByCreationDateOldestOption = '[data-testid="sort-option-date-oldest"]';
    this.moduleList = '[data-testid="module-list"]';
    this.moduleListItem = '[data-testid="module-list-item"]'; // Selector for individual module items
    this.moduleName = '[data-testid="module-name"]'; // Selector for the name within a module item
    this.moduleCreationDate = '[data-testid="module-creation-date"]'; // Selector for creation date within a module item
  }

  /**
   * Navigates to the Modules section/page.
   */
  navigateToModules() {
    this.clickElement(this.modulesNav);
    cy.url().should('include', '/modules'); // Verify navigation
  }

  /**
   * Clicks the sort button to reveal options.
   */
  clickSortButton() {
    this.clickElement(this.sortButton);
  }

  /**
   * Selects a sorting option.
   * @param {string} optionSelector - The selector for the specific sorting option (e.g., this.sortByNameAscendingOption).
   */
  selectSortOption(optionSelector) {
    this.clickElement(optionSelector);
  }

  /**
   * Retrieves the names of all displayed modules.
   * @returns {Cypress.Chainable<string[]>} A Cypress chainable that resolves to an array of module names.
   */
  getModuleNames() {
    return cy.get(this.moduleListItem).find(this.moduleName).map('text').should('be.visible');
  }

  /**
   * Retrieves the creation dates of all displayed modules.
   * Assumes dates are in a parsable format (e.g., ISO 8601).
   * @returns {Cypress.Chainable<Date[]>} A Cypress chainable that resolves to an array of Date objects.
   */
  getModuleCreationDates() {
    return cy.get(this.moduleListItem).find(this.moduleCreationDate).map('text').then((dateStrings) => {
      return dateStrings.map(dateString => new Date(dateString));
    }).should('be.visible');
  }

  /**
   * Verifies the alphabetical sorting of module names.
   * @param {string} order - 'asc' for ascending, 'desc' for descending.
   */
  verifyModuleNamesSorted(order) {
    this.getModuleNames().then((names) => {
      const sortedNames = [...names].sort((a, b) => {
        if (order === 'asc') return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
        return b.localeCompare(a, undefined, { numeric: true, sensitivity: 'base' });
      });
      expect(names).to.deep.eq(sortedNames);
    });
  }

  /**
   * Verifies the sorting of modules by creation date.
   * @param {string} order - 'newest' for newest to oldest, 'oldest' for oldest to newest.
   */
  verifyModuleCreationDatesSorted(order) {
    this.getModuleCreationDates().then((dates) => {
      const sortedDates = [...dates].sort((a, b) => {
        if (order === 'newest') return b.getTime() - a.getTime(); // Newest first
        return a.getTime() - b.getTime(); // Oldest first
      });
      // Convert back to string representations for comparison if needed, or compare Date objects
      expect(dates.map(d => d.toISOString())).to.deep.eq(sortedDates.map(d => d.toISOString()));
    });
  }
}

module.exports = ModulesPage;
