/**
 * Custom command for logging in using cy.session to cache the authenticated state.
 * This prevents repeated logins before each test, speeding up test execution.
 * The session is valid for the entire test run within the same browser context.
 */
Cypress.Commands.add('login', () => {
  const loginPage = new LoginPage();

  // Use cy.session to manage login state.
  // The session will be created once and then reused across tests.
  cy.session(
    'testUserLoginSession', // Unique name for the session
    () => {
