      loginPage.navigateToLogin();
      loginPage.enterUsername(EnvUtils.TEST_EMAIL);
      loginPage.enterPassword(EnvUtils.TEST_PASSWORD);
      loginPage.clickLogin();

      // Assert that login was successful
      cy.url().should('not.include', '/login');
      cy.url().should('include', '/dashboard'); // Assuming successful login redirects to dashboard
      cy.log('User successfully logged in and session established.');
    },
    {
      // Optional: Validate the session here if needed (e.g., check for a cookie)
      validate() {
