## --- Page Object Model (POM)

### `pages/BasePage.js`

An abstract base class for all page objects, providing common functionalities and robust interaction methods.

```javascript
const { expect, Locator, Page } = require('@playwright/test');

/**
 * @class BasePage
 * @description Abstract base class for all Page Objects.
 *              Provides common methods for page interactions and assertions.
 */
class BasePage {
    /**
     * @public
     * @type {Page}
     * @description Playwright's Page object for browser interactions.
     */
    public page;

    /**
     * @param {Page} page - Playwright's Page object.
     */
    constructor(page) {
        this.page = page;
    }

    /**
     * Navigates to a specified URL.
     * @param {string} url - The URL to navigate to.
     * @returns {Promise<void>}
     */
    async goto(url) {
        console.log(`Navigating to: ${url}`);
        await this.page.goto(url, { waitUntil: 'domcontentloaded' });
    }

    /**
     * Clicks on an element identified by a locator.
     * @param {Locator} locator - The Playwright Locator for the element.
     * @returns {Promise<void>}
     */
    async clickElement(locator) {
        console.log(`Clicking element: ${locator}`);
        await this.waitForElement(locator);
        await locator.click();
    }

    /**
     * Fills a text input field identified by a locator.
     * @param {Locator} locator - The Playwright Locator for the input field.
     * @param {string} text - The text to fill into the input.
     * @returns {Promise<void>}
     */
    async fillElement(locator, text) {
        console.log(`Filling element: ${locator} with text: ${text.length > 20 ? text.substring(0, 20) + '...' : text}`);
        await this.waitForElement(locator);
        await locator.fill(text);
    }

    /**
     * Retrieves the text content of an element.
     * @param {Locator} locator - The Playwright Locator for the element.
     * @returns {Promise<string>} The text content of the element.
     */
    async getText(locator) {
        await this.waitForElement(locator);
        const textContent = await locator.textContent();
        console.log(`Retrieved text from ${locator}: ${textContent}`);
        return textContent || '';
    }

    /**
     * Uploads a file to an input field.
     * @param {Locator} locator - The Playwright Locator for the file input element.
     * @param {string | string[]} filePath - The path(s) to the file(s) to upload.
     * @returns {Promise<void>}
     */
    async uploadFile(locator, filePath) {
        console.log(`Uploading file(s) to ${locator}: ${filePath}`);
        await this.waitForElement(locator);
        await locator.setInputFiles(filePath);
    }

    /**
     * Waits for an element to be visible and attached to the DOM.
     * @param {Locator} locator - The Playwright Locator for the element.
     * @param {number} [timeout=10000] - The maximum time to wait in milliseconds.
     * @returns {Promise<void>}
     */
    async waitForElement(locator, timeout = 10000) {
        console.log(`Waiting for element: ${locator} to be visible.`);
        await expect(locator).toBeVisible({ timeout });
    }

    /**
     * Waits for an element to be enabled.
     * @param {Locator} locator - The Playwright Locator for the element.
     * @param {number} [timeout=10000] - The maximum time to wait in milliseconds.
     * @returns {Promise<void>}
     */
    async waitForEnabled(locator, timeout = 10000) {
        console.log(`Waiting for element: ${locator} to be enabled.`);
        await expect(locator).toBeEnabled({ timeout: timeout });
    }

    /**
     * Waits for an element to be disabled.
     * @param {Locator} locator - The Playwright Locator for the element.
     * @param {number} [timeout=10000] - The maximum time to wait in milliseconds.
     * @returns {Promise<void>}
     */
    async waitForDisabled(locator, timeout = 10000) {
        console.log(`Waiting for element: ${locator} to be disabled.`);
        await expect(locator).toBeDisabled({ timeout: timeout });
    }

    /**
     * Waits for a network response with a specific URL or predicate.
     * @param {string | Function} urlOrPredicate - The URL string or a function predicate to match.
     * @param {number} [timeout=30000] - The maximum time to wait in milliseconds.
     * @returns {Promise<object>} The response object.
     */
    async waitForResponse(urlOrPredicate, timeout = 30000) {
        console.log(`Waiting for response matching: ${urlOrPredicate}`);
        return await this.page.waitForResponse(urlOrPredicate, { timeout });
    }

    /**
     * Asserts that an element is visible.
     * @param {Locator} locator - The Playwright Locator for the element.
     * @param {string} [message] - Optional message to display on failure.
     * @returns {Promise<void>}
     */
    async verifyElementVisible(locator, message = `Element ${locator} should be visible`) {
        console.log(`Verifying element visible: ${locator}`);
        await expect(locator, message).toBeVisible();
    }

    /**
     * Asserts that an element contains a specific text.
     * @param {Locator} locator - The Playwright Locator for the element.
     * @param {string} expectedText - The text expected to be present.
     * @param {string} [message] - Optional message to display on failure.
     * @returns {Promise<void>}
     */
    async verifyElementContainsText(locator, expectedText, message = `Element ${locator} should contain text "${expectedText}"`) {
        console.log(`Verifying element ${locator} contains text: "${expectedText}"`);
        await expect(locator, message).toContainText(expectedText);
    }
}

module.exports = BasePage;
```

