class LoginPage extends BasePage {
    /**
     * @public
     * @type {Locator}
     * @description Locator for the username input field.
     */
    public usernameInput;

    /**
     * @public
     * @type {Locator}
     * @description Locator for the password input field.
     */
    public passwordInput;

    /**
     * @public
     * @type {Locator}
     * @description Locator for the login button.
     */
    public loginButton;

    /**
     * @param {Page} page - Playwright's Page object.
     */
    constructor(page) {
        super(page);
        this.usernameInput = page.getByPlaceholder('Username').or(page.getByLabel('Username')).or(page.locator('#username'));
        this.passwordInput = page.getByPlaceholder('Password').or(page.getByLabel('Password')).or(page.locator('#password'));
        this.loginButton = page.getByRole('button', { name: 'Login' }).or(page.locator('button[type="submit"]'));
    }

