        await this.verifyElementVisible(this.loginButton, 'Login button should be visible on login page.');
    }

    /**
     * Performs the login action with provided credentials.
     * @param {string} username - The username to enter.
     * @param {string} password - The password to enter.
     * @returns {Promise<void>}
     */
    async login(username, password) {
        console.log(`Attempting to login with username: ${username}`);
        await this.fillElement(this.usernameInput, username);
        await this.fillElement(this.passwordInput, password); // Password is sensitive, value is masked in logs by fillElement
        await this.clickElement(this.loginButton);
        // Add a waiting mechanism for navigation or dashboard element to appear
        await this.page.waitForURL('**/dashboard**', { waitUntil: 'domcontentloaded' });
        console.log('Login attempt completed.');
    }
}

module.exports = LoginPage;
