// pages/LoginPage.js
const BasePage = require('./BasePage');
const EnvUtils = require('../utils/envUtils');

/**
 * LoginPage class extends BasePage for interacting with the login page.
 */
class LoginPage extends BasePage {
  constructor() {
    super();
    this.usernameField = '[data-testid="username-input"]';
    this.passwordField = '[data-testid="password-input"]';
    this.loginButton = '[data-testid="login-button"]';
    this.errorMessage = '[data-testid="error-message"]';
  }

  /**
   * Navigates to the login page.
   */
  navigateToLogin() {
    this.visit('/login'); // Assuming '/login' is the login path relative to BASE_URL
  }

  /**
   * Enters the username into the username field.
   * @param {string} username - The username to enter.
   */
  enterUsername(username) {
    this.typeText(this.usernameField, username);
  }

  /**
   * Enters the password into the password field.
   * @param {string} password - The password to enter.
   */
  enterPassword(password) {
    this.typeText(this.passwordField, password);
  }

  /**
   * Clicks the login button.
   */
  clickLogin() {
    this.clickElement(this.loginButton);
  }

  /**
   * Performs a complete login action with provided credentials.
   * @param {string} username - The username for login.
   * @param {string} password - The password for login.
   */
  login(username, password) {
    this.navigateToLogin();
    this.enterUsername(username);
    this.enterPassword(password);
    this.clickLogin();
  }

  /**
   * Verifies if an error message is displayed and contains the expected text.
   * @param {string} expectedErrorMessage - The expected error message text.
   */
  verifyErrorMessage(expectedErrorMessage) {
    this.shouldContainText(this.errorMessage, expectedErrorMessage);
  }

  /**
   * Performs login using environment variables.
   */
  loginWithEnvCredentials() {
    this.login(EnvUtils.TEST_EMAIL, EnvUtils.TEST_PASSWORD);
  }
}

module.exports = LoginPage;
