    this.submitButton = '[data-testid="submit-document-button"]';
    this.parsingStatusMessage = '[data-testid="parsing-status-message"]';
    this.extractedContentArea = '[data-testid="extracted-content-area"]';
    this.errorMessageDisplay = '[data-testid="error-message-display"]';
  }

  /**
   * Navigates to the Document Processing interface.
   */
  navigateToDocumentProcessing() {
    this.clickElement(this.documentProcessingNav); // Assuming navigation via a link/button
    cy.url().should('include', '/document-processing'); // Verify navigation
  }

  /**
   * Submits a document for parsing.
   * @param {string} fileName - The name of the file in `cypress/fixtures`.
   * @param {string} mimeType - The MIME type of the file.
   */
  submitDocument(fileName, mimeType) {
    this.uploadFile(this.uploadInput, fileName, mimeType);
    this.clickElement(this.submitButton);
  }

  /**
   * Verifies that the system displays an error message related to parsing.
   * @param {string} expectedErrorText - The expected text within the error message.
   */
  verifyParsingErrorDisplayed(expectedErrorText) {
    this.shouldContainText(this.errorMessageDisplay, expectedErrorText);
  }

  /**
   * Verifies that the system successfully extracted content.
   * @param {string} expectedContentSnippet - A snippet of the text expected to be extracted.
   */
  verifyContentExtracted(expectedContentSnippet) {
    this.shouldContainText(this.extractedContentArea, expectedContentSnippet);
  }

  /**
   * Verifies a specific status message is displayed.
   * @param {string} message - The status message to verify.
   */
  verifyStatusMessage(message) {
    this.shouldContainText(this.parsingStatusMessage, message);
  }
}

